def relation_matrix(degree):
    basis = parts(degree)
    columns = {s: j for j, s in enumerate(basis)}
    rows = []

    for r in range(1, degree + 1):
        for s in sigmas:
            # FZ conditions:
            # 3r >= g+1+|s|, g == r+|s|+1 mod 2.
            if sum(s) > 3*r-g or (g-r-sum(s)-1) % 2:
                continue

            f = F.get((r, s), R.zero())
            if not f:
                continue

            for q in parts(degree-r):
                h = f * prod(ks[x] for x in q)
                row = [K.zero()] * len(basis)
                for exponents, c in h.dict().items():
                    monomial = tuple(
                        i+1
                        for i, m in enumerate(exponents)
                        for _ in range(m)
                    )
                    row[columns[monomial]] = c
                rows.append(row)

    return matrix(K, rows)

