M12 = relation_matrix(12)

# H(s)[j] sums, over set partitions into j blocks,
# the product of 1/(2*sum(block)+1)!!.
@lru_cache(None)
def H(s):
    if not s:
        return (K.one(),)

    out = [K.zero()] * (len(s) + 1)
    first, tail = s[0], s[1:]
